function chunkWithOverlap(words, size, overlap) {
  const chunks = [];
  const step = size;
  for (let i = 0; i < words.length; i += step) {
    chunks.push(words.slice(i, i + size));
    if (i + size >= words.length) break;
  }
  return chunks;
}

