function dedupe(passages) {
  const best = {};
  for (const p of passages) {
    if (!(p.id in best) || p.score > best[p.id].score) best[p.id] = p;
  }
  return Object.values(best).sort((a, b) => b.score - a.score || (a.id < b.id ? -1 : 1));
}

