function rrf(lists, k) {
  const scores = {};
  for (const list of lists) {
    list.forEach((id, i) => {
      scores[id] = (scores[id] || 0) + 1 / (k + i + 1);
    });
  }
  return Object.keys(scores).sort((a, b) => {
    const d = scores[b] - scores[a];
    return Math.abs(d) > 1e-12 ? d : (a < b ? -1 : 1);
  });
}
